@prefix ns2: <ns2:CACAO_00000> .
@prefix ns3: <http://www.cidoc-crm.org/cidoc-crm/> . # Assuming ns3 maps to CIDOC-CRM
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> . # Assuming xsd is used for datatypes

<http://example.org/SestertiusOfMaximinusThrax> rdf:type ns3:E19_Physical_Object ;
    ns3:P1_is_identified_by <http://example.org/SestertiusTitle> ;
    ns3:P129i_is_subject_of <http://example.org/CoinDescription> .

<http://example.org/SestertiusTitle> rdf:type ns3:E35_Title ;
    rdf:value "sestertius of Maximinus Thrax" .

<http://example.org/MaximinusThrax> rdf:type ns3:E21_Person ;
    ns3:P1_is_identified_by <http://example.org/MaximinusThraxName> ;
    ns3:P100i_died_in <http://example.org/DeathOfMaximinusThrax> .

<http://example.org/MaximinusThraxName> rdf:type ns3:E41_Appellation ;
    rdf:value "Maximinus Thrax" .

<http://example.org/DeathOfMaximinusThrax> rdf:type ns3:E69_Death ;
    ns3:P7_took_place_at <http://example.org/Aquileia> .

<http://example.org/Aquileia> rdf:type ns3:E53_Place .

<http://example.org/UniversityOfPadua> rdf:type foaf:Organization .

<http://example.org/Excavations> rdf:type ns3:E7_Activity ;
    ns3:P14_carried_out_by <http://example.org/UniversityOfPadua> .

<http://example.org/CollectionOfCoins> rdf:type skos:Collection ;
    ns3:P140i_was_attributed_by <http://example.org/Excavations> ; # The excavations are where the coins were found/attributed from.
    ns3:P106i_forms_part_of <http://example.org/SestertiusOfMaximinusThrax> . # The sestertius is part of the overall collection but also an individual object.

<http://example.org/CoinDescription> rdf:type ns3:E33_Linguistic_Object ;
    rdf:value "Over 1200 coins have been returned from the excavations (of the University of Padua), among which stands out the sestertius of Maximinus Thrax, the emperor who died in Aquileia at the hands of his own soldiers who had laid siege, without success, the city remained loyal to Rome." .
